I’m seeing a rare race condition in this Rust code using Arc<Mutex<...>> where the program occasionally panics with 'already borrowed' or deadlocks when a callback tries to re-lock. Explain the problem and redesign using channels or interior mutability safely.

let state = Arc::new(Mutex::new(State::new()));
let s2 = state.clone();
register_callback(move || {
    let mut st = s2.lock().unwrap();
    st.on_event();
    st.emit(|msg| {
        // called synchronously
        let mut st2 = s2.lock().unwrap();
        st2.log(msg);
    });
});

